"""zsh-autosuggestions: dim the inline suggestion in a palette grey. New shells.

The suggestion is not accent-y UI — it is intentionally low-contrast filler, so
it takes a tinted grey from `pal["greys"]` (the darkest, most subdued step) via
`ZSH_AUTOSUGGEST_HIGHLIGHT_STYLE`. Applies to new shells (the variable is read
when the plugin loads).
"""
from __future__ import annotations

from .. import config
from ..util import atomic_write


def emit(pal: dict) -> None:
    grey = pal["greys"][str(pal["grey_keys"][0])]
    body = f"""\
# GENERATED by wallpaper-accent — do not edit. Sourced from .zshrc.local.
# The autosuggestion is deliberately subdued: a tinted grey from the palette.
ZSH_AUTOSUGGEST_HIGHLIGHT_STYLE='fg={grey}'
"""
    atomic_write(config.ZSH_AUTOSUGGEST, body)
